local b="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local c={}
for i=1,#b do c[string.byte(b,i)]=i-1 end
local d={} local n=0
local function put(v)
 n=n+1
 d[n]=string.char((v-((n*73+41)%256))%256)
end
for i=1,#a,4 do
 local x,y,z,w=string.byte(a,i,i+3)
 local p,q=c[x],c[y]
 local r,t=c[z],c[w]
 if p==nil or q==nil then error("Invalid payload",0) end
 put(p*4+math.floor(q/16))
 if z~=61 then
  if r==nil then error("Invalid payload",0) end
  put((q%16)*16+math.floor(r/4))
  if w~=61 then
   if t==nil then error("Invalid payload",0) end
   put((r%4)*64+t)
  end
 end
